import{_ as i,o as r,c as o,ae as a}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1776334221000}'),t={name:"guide/architecture.md"};function l(n,e,d,s,c,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>SweetEditor is built around a strict split between a native editor kernel and a Kotlin/Compose wrapper.</p><h2 id="high-level-structure" tabindex="-1">High-level Structure <a class="header-anchor" href="#high-level-structure" aria-label="Permalink to &quot;High-level Structure&quot;">​</a></h2><ul><li><code>editor-core</code>: native editor kernel</li><li><code>editor-compose</code>: Kotlin Multiplatform wrapper and Compose UI integration</li><li><code>example</code>: reference application</li><li><code>platform-demo</code>: platform-specific demos and experiments</li></ul><h2 id="core-principle" tabindex="-1">Core Principle <a class="header-anchor" href="#core-principle" aria-label="Permalink to &quot;Core Principle&quot;">​</a></h2><p>The project is <strong>not</strong> a <code>BasicTextField</code> enhancement. It is a dedicated editor architecture:</p><ul><li>native kernel owns editing semantics</li><li>Kotlin layer owns state wrapping, protocol decoding, and Compose integration</li><li>Compose layer consumes render models instead of re-deriving editor state</li></ul><h2 id="layer-responsibilities" tabindex="-1">Layer Responsibilities <a class="header-anchor" href="#layer-responsibilities" aria-label="Permalink to &quot;Layer Responsibilities&quot;">​</a></h2><h2 id="native-core" tabindex="-1">Native Core <a class="header-anchor" href="#native-core" aria-label="Permalink to &quot;Native Core&quot;">​</a></h2><p>The native core is responsible for:</p><ul><li>document model</li><li>editing algorithms</li><li>cursor and selection semantics</li><li>render model generation</li><li>fold state, bracket matching, highlighting, diagnostics payloads</li><li>C API surface exported to Kotlin</li></ul><p>The core used by this repository is based on:</p><ul><li><a href="https://github.com/FinalScave/OpenSweetEditor" target="_blank" rel="noreferrer">FinalScave/OpenSweetEditor</a></li></ul><h2 id="kotlin-wrapper" tabindex="-1">Kotlin Wrapper <a class="header-anchor" href="#kotlin-wrapper" aria-label="Permalink to &quot;Kotlin Wrapper&quot;">​</a></h2><p>The Kotlin Multiplatform layer is responsible for:</p><ul><li>safe native bridge calls</li><li>binary protocol parsing</li><li>lifecycle management of native-backed documents</li><li>public APIs such as controllers, providers, and events</li><li>platform source set isolation</li></ul><p>Typical types in this layer include:</p><ul><li><code>SweetEditorController</code></li><li><code>EditorDocument</code></li><li><code>DecorationProvider</code></li><li><code>CompletionProvider</code></li><li><code>InlineSuggestionController</code></li></ul><h2 id="compose-ui-layer" tabindex="-1">Compose UI Layer <a class="header-anchor" href="#compose-ui-layer" aria-label="Permalink to &quot;Compose UI Layer&quot;">​</a></h2><p>The Compose layer is responsible for:</p><ul><li>rendering the editor surface</li><li>pointer, keyboard, and IME integration</li><li>popup UI such as completion and inline suggestion action bars</li><li>text measurement and theme application</li></ul><h2 id="render-flow" tabindex="-1">Render Flow <a class="header-anchor" href="#render-flow" aria-label="Permalink to &quot;Render Flow&quot;">​</a></h2><p>The typical rendering pipeline is:</p><ol><li>editor input is sent through the Kotlin wrapper</li><li>native core updates document and render state</li><li>core emits render payload / model data</li><li>Kotlin decodes payload into Compose-consumable models</li><li>Compose draws the editor surface from that render model</li></ol><h2 id="decoration-flow" tabindex="-1">Decoration Flow <a class="header-anchor" href="#decoration-flow" aria-label="Permalink to &quot;Decoration Flow&quot;">​</a></h2><p>The decoration pipeline is intentionally layered:</p><ol><li>Compose/Kotlin provider reads <code>DecorationProviderContext</code></li><li>provider returns <code>DecorationUpdate</code></li><li>manager merges or replaces provider-owned data</li><li>wrapper encodes the aggregated result</li><li>native core consumes the decoration payload</li><li>render model reflects the final result</li></ol><h2 id="important-boundaries" tabindex="-1">Important Boundaries <a class="header-anchor" href="#important-boundaries" aria-label="Permalink to &quot;Important Boundaries&quot;">​</a></h2><ul><li>Do not re-implement native editing algorithms in Kotlin</li><li>Keep common abstractions in <code>commonMain</code></li><li>Keep platform-specific hooks in their own source sets</li><li>Treat the render model as the single source of truth for drawing</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./getting-started">Getting Started</a></li><li><a href="./theme-appearance">Theme / Appearance</a></li><li><a href="./api-overview">API Overview</a></li><li><a href="./platform-support">Platform Support</a></li></ul>',31)])])}const m=i(t,[["render",l]]);export{u as __pageData,m as default};
